<template><AppPage title="刊登异常" eyebrow="LISTING EXCEPTIONS" subtitle="处理校验、排队和执行过程中的异常记录。" capability="connected"><el-table :data="rows" v-loading="loading" border><el-table-column prop="task" label="任务" width="100" /><el-table-column prop="error_code" label="错误码" width="150" /><el-table-column prop="message" label="错误信息" /><el-table-column prop="is_resolved" label="已解决" width="100"><template #default="{row}"><el-tag :type="row.is_resolved?'success':'danger'">{{ row.is_resolved?'是':'否' }}</el-tag></template></el-table-column><el-table-column prop="created_at" label="时间" width="180" /></el-table></AppPage></template>
<script setup>import { onMounted,ref } from 'vue';import AppPage from '../../components/AppPage.vue';import{fetchListingExceptions}from'../../api/listings';const rows=ref([]),loading=ref(false);async function load(){loading.value=true;const r=await fetchListingExceptions();rows.value=r.success?(r.data?.results||r.data||[]):[];loading.value=false;}onMounted(load);</script>
